def merge_top_k(shard_top_lists: list[list[tuple[int, str]]], t: int = 100) -> list[tuple[int, str]]:
    if t <= 0:
        return []
    merged = heapq.merge(*shard_top_lists, key=lambda item: -item[0])
    out: list[tuple[int, str]] = []
    for item in merged:
        out.append(item)
        if len(out) == t:
            break
    return out
